import itertools
import json


def task_func(data_list, json_file_name="mean_values.json"):
    """Return positional numeric means, optionally exporting them as JSON."""
    numeric_columns = itertools.islice(zip(*data_list), 1, None)
    results = {
        f"Position {i}": float(np.mean(column))
        for i, column in enumerate(numeric_columns, start=1)
    }

    if json_file_name:
        with open(json_file_name, "w", encoding="utf-8") as json_file:
            json.dump(results, json_file)

    return results

