import itertools
import math


def task_func(x):
    """Return a nonempty subsequence with minimum total length, or [] if empty."""
    minimum = math.inf
    result = []
    for size in range(1, len(x) + 1):
        for subsequence in itertools.combinations(x, size):
            total = sum(x[key] for key in subsequence)
            if total < minimum:
                minimum = total
                result = list(subsequence)
    return result

