import numpy as np
import pandas as pd
from datetime import datetime

DATE_FORMAT = '%Y-%m-%d %H:%M:%S'


def task_func(result):
    """Summarize numeric from_user values and append the current local time."""
    values = [item['from_user'] for item in result if 'from_user' in item]
    if not values:
        summary = dict.fromkeys(('mean', 'median', 'min', 'max', 'std'), np.nan)
    else:
        try:
            data = np.asarray(values)
        except (TypeError, ValueError) as exc:
            raise ValueError('from_user values must be numeric') from exc
        if data.ndim != 1 or data.dtype.kind not in 'biufc':
            raise ValueError('from_user values must be numeric')
        summary = {
            'mean': np.mean(data),
            'median': np.median(data),
            'min': np.min(data),
            'max': np.max(data),
            'std': np.std(data),
        }
    summary['current_time'] = datetime.now().strftime(DATE_FORMAT)
    return pd.Series(summary)

