    def worker(index):
        time.sleep(delay_time)
        messages[index] = f'Delay in thread {index} completed'

    threads = [
        threading.Thread(target=worker, args=(index,))
        for index in range(num_threads)
    ]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    return messages

