from itertools import cycle
from random import choice, seed


def task_func(n_colors, colors=['Red', 'Green', 'Blue', 'Yellow', 'Purple'], rng_seed=None):
    """Return alternating cyclic and random colors, starting with a cyclic color."""
    if n_colors <= 0:
        return []

    seed(rng_seed)
    cyclic_colors = cycle(colors)
    return [
        next(cyclic_colors) if i % 2 == 0 else choice(colors)
        for i in range(n_colors)
    ]

