from collections import Counter
import re


def task_func(word: str) -> list:
    """Return the most frequent adjacent letter pair after cleaning the input."""
    cleaned = re.sub(r"[^a-z]", "", word.lower())
    if len(cleaned) < 2:
        return []

    pairs = Counter(cleaned[i:i + 2] for i in range(len(cleaned) - 1))
    return pairs.most_common(1)

